// DERIVED FROM. The policy-to-policy relation of the Visualisation Note §4
// (prov:wasDerivedFrom) as an affordance: in edit mode the card's "Derived
// from" field lists every link it carries, each with a ✕, and a use-existing
// button that opens the SAME candidate listbox the rule sections use.
// Generic on purpose — any policy may be derived from any other; only the
// ORDER of the candidates knows that an agreement usually follows an offer.
import { createMemo, For, Show } from 'solid-js';
import type { JSX } from 'solid-js';
import { text, setNotice } from '../../../stores/view.js';
import { graphVersion } from '../../../stores/corpus.js';
import { curie } from '../../../model/parse.js';
import { ProvRef } from '../../card/body-rows.jsx';
import { kindOf } from '../../card/card.jsx';
import { KindPill } from '../../shared/chip.jsx';
import type { CardKind } from '../../shared/chip.jsx';
import type { Quad } from '../../../model-boundary.js';
import { Button } from '../button.jsx';
import { SecIconButton, ReuseIcon, requestFocusOn } from './card-edit.jsx';
import { editState } from './state.jsx';
import { reuseState } from './reuse.jsx';
import { closeReuse, openKey, reuseKey, toggleReuse } from './reuse-open.js';
import { PickList, graphOf, rank } from './reuse-list.jsx';
import type { Candidate } from './reuse-list.jsx';
import { termOf } from './anchor.js';
import { showToast } from '../toast.jsx';
import type { Core } from './core.js';
import type { CardHookCtx } from '../../shared/edit-hook.jsx';
import '../edit.css';

const LIST_KIND = 'derivedFrom';

const NOTICE: Record<string, string> = {
  unknown: 'edit.derivedUnknown',
  wrongKind: 'edit.derivedNotPolicy',
  alreadyLinked: 'edit.derivedAlready',
};

// The kinds that usually stand ABOVE this one in the chain: an agreement
// follows the offer and the request it settles, a request follows the offer it
// asks about. Not a profile rule — a reading order.
const ABOVE: Record<string, string[]> = {
  agreement: ['offer', 'request'],
  request: ['offer'],
};

interface PolicyOption {
  iri: string; curie: string | null; label: string; kind: string; source: string;
}

/** The file a candidate stands in — its herkomst, in one short word. */
export function sourceName(graphIri: string): string {
  const s = String(graphIri || '').replace(/[#?].*$/, '').replace(/\/+$/, '');
  return s ? (s.split('/').pop() || s) : '';
}

export function derivedTier(c: PolicyOption, ownKind: string, ownSource: string): number {
  if ((ABOVE[ownKind] || []).includes(c.kind)) return 0;
  if (ownSource && c.source === ownSource) return 1;
  return 2;
}

export function DerivedFromField(props: { core: Core; ctx: CardHookCtx }): JSX.Element {
  const term = createMemo(() => termOf(props.ctx.pol));
  const key = () => reuseKey(term()?.id || term()?.value || '', LIST_KIND);
  const kind = () => kindOf(props.ctx.pol) as string;

  const linked = createMemo(() => {
    void graphVersion();
    const g = props.core.graph();
    const t = term();
    if (!g || !t) return [] as { iri: string; curie: string | null; label: string | null }[];
    return props.core.edit.derivedObjects(g, t)
      .map((iri) => ({ iri, curie: curie(iri), label: null }));
  });

  const options = createMemo<PolicyOption[]>(() => {
    void graphVersion();
    const g = props.core.graph();
    const t = term();
    if (!g || !t) return [];
    return (props.core.edit.policyOptions(g) as PolicyOption[])
      .filter((o) => props.core.edit.derivedCheck(g, t, o.iri).ok);
  });

  const ranked = createMemo<Candidate[]>(() => {
    if (openKey() !== key()) return [];
    const own = graphOf(props.core, term());
    const rows = options().map((o) => ({
      ...o, provenance: sourceName(o.source) ? [sourceName(o.source)] : [],
    }));
    return rank(rows, (r) => derivedTier(r, kind(), own));
  });

  const attach = (iri: string): void => {
    const g = props.core.graph();
    const t = term();
    const verdict = props.core.edit.derivedCheck(g, t, iri);
    if (!verdict.ok) {
      setNotice(NOTICE[verdict.reason || ''] || 'edit.invalidIri', { input: iri });
      return;
    }
    void props.core.execute((f) => { props.core.edit.attachDerived(f, t, iri); }, { group: true })
      .then((ok) => {
        if (!ok) return;
        showToast('edit.derivedLinked');
        closeReuse();
        requestFocusOn(t);
      })
      .catch(() => {});
  };

  const pickState = createMemo(() => reuseState({
    core: props.core,
    term: term(),
    count: options().length,
    title: text('edit.derived'),
    none: 'edit.derivedNone',
    toggle: () => toggleReuse(key()),
  }));

  return (
    <span class="derived-field">
      <For each={linked()}>{(d) => (
        <span class="derived-link">
          <ProvRef d={d} />
          <DerivedCross core={props.core} term={term()} iri={d.iri} />
        </span>
      )}</For>
      <SecIconButton
        cls="sec-add-btn derived-reuse"
        name={text('edit.derived')}
        state={pickState()}
        icon={<ReuseIcon />}
      />
      <PickList
        listKey={key}
        candidates={ranked}
        onPick={attach}
        ariaLabel={text('edit.derivedChoose')}
        idPrefix="derived-pick"
        badge={(c) => (
          <span class="ghost-badge">
            <KindPill kind={(c as Candidate & { kind: string }).kind as CardKind} />
          </span>
        )}
        scopeSel=".derived-field"
        buttonSel=".derived-reuse"
        looseKey="edit.derivedLoose"
      />
    </span>
  );
}

function DerivedCross(props: {
  core: Core; term: unknown; iri: string;
}): JSX.Element {
  const quads = createMemo<Quad[]>(() => {
    void graphVersion();
    const g = props.core.graph();
    return g && props.term ? props.core.edit.derivedQuads(g, props.term, props.iri) : [];
  });
  const state = () => editState(props.core, {
    allow: quads().length > 0 && props.core.quadsInEditSource(quads()),
    title: text('edit.derivedRemove'),
    action: () => {
      void props.core.execute(
        (f) => props.core.edit.detachDerived(f, props.term, props.iri), { group: true },
      )
        .then((ok) => { if (ok) showToast('edit.derivedRemoved'); })
        .catch(() => {});
    },
    blocked: quads(),
    notApplicable: text('edit.removeNoLink'),
    unlockable: true,
  });
  return (
    <Show when={props.iri}>
      <Button
        label="✕"
        cls={`derived-x${state().on ? '' : (state().action ? ' locked' : ' action-off')}`}
        title={state().title}
        ariaLabel={state().title}
        onClick={(e) => state().action?.(e)}
      />
    </Show>
  );
}
