import { sourceRows, editSource as currentSource, makeEditable, opfsOn } from '../../../stores/source-management.js';
import { graph } from '../../../stores/corpus.js';
import { jump } from '../../../stores/view.js';
import { attachEditHooks } from '../../shared/edit-hook.jsx';
import type { Quad, Term } from '../../../model-boundary.js';
import type { ReadStore } from './anchor.js';
import type { EditApi, Core, UnlockTarget } from './core.js';
import {
  GroupRuleGhost, CardHeaderStrip, SectionAddButtons, SectionReuse, NewPolicyGhost,
} from './card-edit.jsx';
import {
  CollectionRefinementGhost, RuleDutyGhost, RuleGrip, RuleStrip, ConstraintGhost,
  ConstraintStrip,
} from './row-edit.jsx';
import { TargetGhost, TargetCross } from './target-edit.jsx';
import { DerivedFromField } from './derived-edit.jsx';

export function pickUnlockGraph(
  quads: Quad[], currentGraph?: string | null,
): string | null {
  const counts = new Map<string, number>();
  for (const q of quads) {
    const name = q.graph && q.graph.value;
    if (!name) continue;
    counts.set(name, (counts.get(name) || 0) + 1);
  }
  const bySize = [...counts.entries()].sort((a, b) => b[1] - a[1]);
  if (!bySize.length) return null;
  const [winner] = bySize[0];
  if (currentGraph && winner === currentGraph) return null;
  return winner;
}

function unlockTarget(term: Term | null, blocked?: Quad[] | null): UnlockTarget | null {
  if (!opfsOn()) return null;
  const g = graph() as unknown as ReadStore | null;
  const quads = (blocked && blocked.length)
    ? blocked
    : (g && term ? g.getQuads(term, null, null, null) : []);
  if (!quads.length) return null;
  const current = currentSource();
  const winner = pickUnlockGraph(quads, current ? current.graph : null);
  if (!winner) return null;
  const source = sourceRows()
    .find((r) => r.graph === winner && r.kind === 'ttl' && !r.fromSparql);
  if (!source) return null;
  return {
    name: source.name || source.url || winner,
    current: current ? (current.name || current.url || undefined) : undefined,
    warn: !source.opfs,
    make: () => makeEditable(source),
  };
}

export async function attachIntegration(): Promise<void> {
  const [coreModule, editModule] = await Promise.all([
    import('../../../stores/edit.js'),
    import('../../../model/edit.js'),
  ]);
  const core: Core = {
    graph: () => graph() as unknown as ReadStore | null,
    execute: (fn, options) => coreModule.execute(fn as never, options),
    editable: (term) => coreModule.editable(term as never),
    quadsInEditSource: (quads) => coreModule.quadsInEditSource(quads),
    hasEditSource: () => !!currentSource(),
    edit: editModule as unknown as EditApi,
    jump: (ref, options) => { void jump(ref, options); },
    unlockTarget,
  };
  attachEditHooks({
    cardHeader: (ctx) => CardHeaderStrip({ core, ctx }),
    derivedFrom: (ctx) => DerivedFromField({ core, ctx }),
    sectionAdd: (ctx) => SectionAddButtons({ core, ctx }),
    sectionReuse: (ctx) => SectionReuse({ core, ctx }),
    ruleGrip: (ctx) => RuleGrip({ core, ctx }),
    ruleStrip: (ctx) => RuleStrip({ core, ctx }),
    dutyGhost: (ctx) => RuleDutyGhost({ core, ctx }),
    groupGhost: (ctx) => GroupRuleGhost({ core, ctx }),
    targetCross: (ctx) => TargetCross({ core, ctx }),
    targetGhost: (ctx) => TargetGhost({ core, ctx }),
    constraintStrip: (ctx) => ConstraintStrip({ core, ctx }),
    constraintGhost: (ctx) => ConstraintGhost({ core, ctx }),
    collectionGhost: (ctx) => CollectionRefinementGhost({ core, ctx }),
    newPolicy: (ctx) => NewPolicyGhost({ core, ctx }),
  });
}
